parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": [
        "01_ความปลอดภัยและบริหารความเสี่ยง",
        "02_จัดซื้อจัดจ้างและพัสดุ",
        "03_เตรียมรับการตรวจและนิเทศ",
        "04_กิจกรรมพัฒนาชุมชนและนักเรียน",
        "05_เทคโนโลยีสารสนเทศและข้อมูล"
      ],
      "description": "หมวดหมู่คณะทำงาน/คณะกรรมการที่ตรงกับเนื้อหาการประชุมนี้มากที่สุด ต้องเลือกมาหนึ่งค่าจากตัวเลือกที่กำหนดเท่านั้น"
    },
    "meetingTitle": {
      "type": "string",
      "description": "ชื่อเรื่อง/หัวข้อการประชุมโดยย่อ"
    },
    "meetingDate": {
      "type": "string",
      "description": "วันที่ประชุม ตามที่ระบุในเอกสารต้นฉบับ"
    },
    "typoCorrections": {
      "type": "string",
      "description": "รายการคำผิด/คำตกที่ตรวจพบ รูปแบบ 'คำเดิม → คำที่แก้ไข' แต่ละรายการขึ้นบรรทัดใหม่ หรือ 'ไม่พบคำผิด' ถ้าไม่พบ"
    },
    "ignoredContent": {
      "type": "string",
      "description": "ข้อความที่ไม่เกี่ยวข้องกับวาระการประชุมที่ตัดออกจากสรุป (เช่น คุยเล่น เรื่องส่วนตัว) หรือ 'ไม่มี' ถ้าไม่พบ"
    },
    "keyParticipants": {
      "type": "string",
      "description": "ผู้เข้าร่วมสำคัญโดยสรุป ไม่ต้องคัดลอกทั้งหมด"
    },
    "discussionSummary": {
      "type": "string",
      "description": "สรุปประเด็นสำคัญที่หารือ เป็น bullet point กระชับกว่าต้นฉบับ"
    },
    "decisions": {
      "type": "string",
      "description": "มติ/ข้อสั่งการ ระบุผู้รับผิดชอบและกำหนดเวลาให้ชัดเจน"
    },
    "nextMeeting": {
      "type": "string",
      "description": "วันนัดประชุมครั้งถัดไป ถ้ามีระบุไว้ในเอกสาร"
    }
  },
  "required": [
    "category",
    "meetingTitle",
    "meetingDate",
    "typoCorrections",
    "ignoredContent",
    "keyParticipants",
    "discussionSummary",
    "decisions",
    "nextMeeting"
  ]
}

